        if b["state"] != a["state"]:
            out.append({"kind": "closed" if a["state"] == "CLOSED" else "reopened", "item": key, "before": b["state"], "after": a["state"]})
        added = sorted(set(a["blocked_by"]) - set(b["blocked_by"]))
